package main

import (
	"html/template"
	"net/url"
)

var adminTemplate = template.Must(template.New("admin").Funcs(template.FuncMap{"urlquery": url.QueryEscape}).Parse(`<!doctype html>
<html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ファイル転送 操作画面</title>
<style>
:root{--bg:#eef1f4;--card:#fff;--text:#111827;--sub:#4b5563;--line:#cfd5dc;--accent:#075cab;--good:#166534;--danger:#b42318;--warnbg:#fff8e6;--warn:#7a4b00}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:"Segoe UI","Yu Gothic UI",sans-serif}.wrap{max-width:1220px;margin:0 auto;padding:20px 18px 54px}.hero{background:#18324a;color:#fff;padding:20px 24px;border-radius:8px;margin-bottom:16px;border-bottom:5px solid #0b69b7}.hero h1{margin:0;font-size:32px}.hero p{margin:7px 0 0;color:#e4edf5;font-size:16px}.keepOpen{background:#fff8e6;border:2px solid #e3b341;color:#654200;padding:12px 16px;border-radius:6px;margin-bottom:16px;font-weight:700}.card{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:20px;margin-bottom:16px;box-shadow:0 1px 2px rgba(0,0,0,.05)}.flow{display:grid;grid-template-columns:minmax(0,1fr) 90px minmax(0,1fr);align-items:center;gap:12px}.flowItem{text-align:center}.stepNo{display:inline-grid;place-items:center;width:38px;height:38px;background:#18324a;color:#fff;border-radius:50%;font-size:20px;font-weight:800;margin-bottom:8px}.stepTitle{font-size:23px;font-weight:800;margin-bottom:5px}.lead{color:var(--sub);font-size:14px;margin-bottom:14px;min-height:40px}.qr{width:230px;height:230px;background:#fff;border:2px solid #9ca3af;padding:9px;object-fit:contain}.arrow{font-size:76px;line-height:1;color:#64748b;font-weight:900;text-align:center}.cred{margin:13px auto 0;max-width:360px;background:#f7f8fa;border:1px solid var(--line);padding:12px;text-align:left;border-radius:6px}.credRow{display:grid;grid-template-columns:105px 1fr;gap:10px;padding:4px 0}.credLabel{color:var(--sub);font-size:13px}.credValue{font-size:17px;font-weight:800;overflow-wrap:anywhere}.code{font-family:Consolas,monospace}.help{margin-top:16px;text-align:left}.help summary{cursor:pointer;font-weight:700;color:#274c6b;padding:10px 0}.altGrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px;margin-top:8px}.alt{border:1px solid var(--line);background:#f8fafc;padding:12px;border-radius:6px;text-align:center}.alt .qr{width:170px;height:170px}.muted{color:var(--sub);font-size:13px}.url{overflow-wrap:anywhere;font-size:13px;margin-top:6px}.sectionHead{display:flex;align-items:flex-start;gap:12px;margin-bottom:14px}.sectionHead .stepNo{flex:0 0 38px;margin:0}.sectionTitle{font-size:24px;font-weight:800}.toolRow{display:flex;flex-wrap:wrap;gap:10px}.btn,.fileLabel{border:0;border-radius:6px;padding:12px 16px;font-size:15px;font-weight:700;cursor:pointer}.primary{background:var(--accent);color:#fff}.secondary{background:#e5e7eb;color:#111827;border:1px solid #cbd0d6}.danger{background:#fee4e2;color:var(--danger);border:1px solid #f5b7b1}.fileLabel input{display:none}.subgrid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px}.panel{background:#f8fafc;border:1px solid var(--line);border-radius:6px;padding:15px}.panel h3{margin:0 0 5px;font-size:18px}.list{margin-top:10px}.file{display:flex;padding:9px 0;border-bottom:1px solid #d9dde2;gap:10px}.file:last-child{border-bottom:0}.file span:first-child{flex:1;overflow-wrap:anywhere}.status{color:var(--sub);font-size:14px;margin-top:10px}.ok{color:var(--good);font-weight:700}.stopBox{display:flex;justify-content:space-between;align-items:center;gap:18px}.stopBox .btn{font-size:17px;padding:13px 22px}.warning{background:var(--warnbg);border:1px solid #e6c15a;color:var(--warn);padding:11px 13px;border-radius:6px;margin-top:12px}@media(max-width:820px){.flow{grid-template-columns:1fr}.arrow{transform:rotate(90deg);font-size:54px}.subgrid{grid-template-columns:1fr}.lead{min-height:auto}.stopBox{align-items:flex-start;flex-direction:column}.qr{width:210px;height:210px}}
</style></head><body><div class="wrap">
<div class="hero"><h1>スマートフォンとファイルを送受信</h1><p>{{.DeviceName}} と iPhone / Android を直接つなぎます。左から右へ進んでください。</p></div>
<div class="keepOpen">この画面はファイル転送が終わるまで閉じないでください。終了するときは、画面下の「ファイル転送を終了」を押してください。</div>
<div class="card">
<div class="flow">
<div class="flowItem"><div class="stepNo">1</div><div class="stepTitle">Wi‑Fiに接続</div><div class="lead">スマートフォンのカメラでこのQRコードを読み取ります。</div>{{if .WiFiQR}}<img class="qr" src="/qr.svg?text={{urlquery .WiFiQR}}" alt="Wi-Fi接続用QRコード">{{end}}<div class="cred"><div class="credRow"><div class="credLabel">Wi‑Fi名</div><div class="credValue">{{.WiFiSSID}}</div></div><div class="credRow"><div class="credLabel">パスワード</div><div class="credValue code">{{.WiFiPassword}}</div></div><div class="muted" style="margin-top:7px">「インターネットなし」と表示されても正常です。</div></div></div>
<div class="arrow" aria-hidden="true">➜</div>
<div class="flowItem"><div class="stepNo">2</div><div class="stepTitle">転送画面を開く</div><div class="lead">Wi‑Fiへの接続が終わったら、このQRコードを読み取ります。</div>{{range $i,$u := .URLs}}{{if eq $i 0}}<img class="qr" src="/qr.svg?text={{urlquery $u.URL}}" alt="転送画面用QRコード"><div class="muted" style="margin-top:10px">QRコードが読めない場合：<div class="url">{{$u.URL}}</div></div>{{end}}{{else}}<div class="warning">転送用ネットワークを確認できませんでした。Wi‑Fiの状態を確認して、アプリを起動し直してください。</div>{{end}}</div>
</div>
<details class="help"><summary>転送画面につながらないとき</summary><div class="muted">上のQRコードで開けない場合だけ、以下の別の接続先を試してください。</div><div class="altGrid">{{range $i,$u := .URLs}}{{if ne $i 0}}<div class="alt"><img class="qr" src="/qr.svg?text={{urlquery $u.URL}}" alt="予備の転送画面用QRコード"><div style="font-weight:700;margin-top:6px">{{$u.Interface}}</div><div class="muted">{{$u.IP}}</div><div class="url">{{$u.URL}}</div></div>{{end}}{{end}}</div></details>
</div>
<div class="card"><div class="sectionHead"><div class="stepNo">3</div><div><div class="sectionTitle">ファイルを送受信</div><div class="muted">スマホから送る場合はスマホ画面を操作します。PCから渡す場合は下のボタンを使います。</div></div></div>
<div class="toolRow"><label class="fileLabel primary">スマホに渡すファイルを選ぶ<input id="sharePick" type="file" multiple></label><button class="btn secondary" onclick="openFolder('send')">スマホに渡すファイルを確認</button><button class="btn secondary" onclick="openFolder('receive')">スマホから受け取ったファイルを開く</button></div><div id="shareStatus" class="status"></div>
<div class="subgrid"><div class="panel"><h3>スマホに渡すファイル</h3><div class="muted">ここに表示されているファイルをスマホから受け取れます。</div><div id="sendList" class="list"></div><button class="btn danger" onclick="clearSide('send')" style="margin-top:12px">スマホ向けの共有をすべて解除</button></div><div class="panel"><h3>スマホから受け取ったファイル</h3><div class="muted">スマートフォンからこのPCへ送られたファイルです。</div><div id="recvList" class="list"></div><button class="btn danger" onclick="clearSide('receive')" style="margin-top:12px">受け取ったファイルをすべて削除</button></div></div></div>
<div class="card stopBox"><div><strong>ファイル転送が終わったら</strong><div class="muted" style="margin-top:4px">このボタンで転送用Wi‑Fiを停止してから画面を閉じてください。</div></div><button class="btn danger" onclick="stopApp()">ファイル転送を終了</button></div>
</div>
<script>
const admin='/admin/{{.AdminToken}}';let allowClose=false;
window.addEventListener('beforeunload',e=>{if(!allowClose){e.preventDefault();e.returnValue=''}});
function fmt(n){if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';if(n<1073741824)return(n/1048576).toFixed(1)+' MB';return(n/1073741824).toFixed(2)+' GB'}
document.getElementById('sharePick').addEventListener('change',async e=>{const st=document.getElementById('shareStatus');for(const f of e.target.files){st.textContent='準備中: '+f.name;await rawUpload(f)}st.textContent='スマホに渡すファイルを用意しました。';st.className='status ok';e.target.value='';loadStatus()});
function rawUpload(f){return new Promise(res=>{const x=new XMLHttpRequest();x.open('POST',admin+'/upload?name='+encodeURIComponent(f.name));x.onload=()=>res();x.onerror=()=>res();x.send(f)})}
async function openFolder(which){await fetch(admin+'/open?which='+which,{method:'POST'})}
async function clearSide(which){if(!confirm(which==='send'?'スマホに渡すファイルの共有をすべて解除しますか？':'スマホから受け取ったファイルをすべて削除しますか？'))return;await fetch(admin+'/clear-'+which,{method:'POST'});loadStatus()}
async function loadStatus(){try{const r=await fetch(admin+'/api/status',{cache:'no-store'});const s=await r.json();render('sendList',s.send,'スマホに渡すファイルはありません');render('recvList',s.receive,'まだファイルを受け取っていません')}catch(e){}}
function render(id,fs,empty){const el=document.getElementById(id);if(!fs.length){el.innerHTML='<div class="muted" style="padding:10px 0">'+empty+'</div>';return}el.innerHTML='';for(const f of fs){const d=document.createElement('div');d.className='file';const n=document.createElement('span');n.textContent=f.name;const z=document.createElement('span');z.className='muted';z.textContent=fmt(f.size);d.append(n,z);el.appendChild(d)}}
async function stopApp(){if(!confirm('ファイル転送を終了しますか？'))return;allowClose=true;await fetch(admin+'/stop',{method:'POST'});document.body.innerHTML='<div style="font-family:Segoe UI,Yu Gothic UI,sans-serif;max-width:700px;margin:80px auto;padding:32px"><h1>ファイル転送を終了しました</h1><p>転送用Wi‑Fiを停止しました。この画面は閉じても大丈夫です。</p></div>'}
loadStatus();setInterval(loadStatus,3000);
</script></body></html>`))
